document.addEventListener("DOMContentLoaded", async () => {
  const h = document.querySelector(".study-tabs"),
    m = document.getElementById("topic-content"),
    g = document.getElementById("upsc-page-data");
  if (!h || !m || !g) {
    console.error("Missing essential elements for UPSC renderer.");
    return;
  }
  const t = JSON.parse(g.textContent),
    f = ["overview", "concepts", "visual", "comparisons", "practice", "mains", "revision", "test"];

  await (async () => {
    const o = window.location.pathname.replace(/\/?index\.html$/, "/").replace(/\/?$/, "/");
    (await Promise.all(
      f.map(async (i) => {
        try {
          const r = await fetch(`${o}tabs/${i}.json`, { cache: "no-cache" });
          return r.ok ? [i, await r.json()] : null;
        } catch (r) {
          console.warn(`Could not load UPSC tab JSON: ${i}`, r);
          return null;
        }
      })
    ))
      .filter(Boolean)
      .forEach(([i, r]) => {
        t[i] = r;
      });
  })();

  const a = (o) => {
    if (!o) return "";
    if (typeof o === "string") return `<span class="lang-en">${o}</span><span class="lang-hi">${o}</span>`;
    if (o && o.en) return `<span class="lang-en">${o.en}</span><span class="lang-hi">${o.hi || o.en}</span>`;
    return "";
  };

  const b = (o) => {
    const arr = Array.from(o);
    for (let c = arr.length - 1; c > 0; c--) {
      const i = Math.floor(Math.random() * (c + 1));
      [arr[c], arr[i]] = [arr[i], arr[c]];
    }
    return arr;
  };

  const $ = (o) => {
    let c = "";
    switch (o) {
      case "overview":
        c = `
                    <h2>${a(t.overview.title)}</h2>
                    <p>${a(t.overview.definition)}</p>
                    <h3><span class="lang-en">Importance in UPSC</span><span class="lang-hi">UPSC में महत्व</span></h3>
                    <p>${a(t.overview.importanceInUpsc)}</p>
                    <h3><span class="lang-en">Learning Outcomes</span><span class="lang-hi">सीखने के परिणाम</span></h3>
                    <ul>
                        ${(t.learningObjectives || []).map((s) => `<li>${a(s)}</li>`).join("")}
                    </ul>
                    ${
                      t.overview.prerequisites && t.overview.prerequisites.length > 0
                        ? `
                    <h3><span class="lang-en">Prerequisites</span><span class="lang-hi">पूर्व-आवश्यकताएं</span></h3>
                    <ul>
                        ${t.overview.prerequisites.map((s) => `<li>${a(s)}</li>`).join("")}
                    </ul>
                    `
                        : ""
                    }
                `;
        break;
      case "concepts":
        c = `
                    ${(t.concepts.sections || [])
                      .map((s) => {
                        let e = `<h3>${a(s.title)}</h3>`;
                        return s.type === "paragraph"
                          ? (e += `<p>${a(s.content)}</p>`)
                          : s.type === "table"
                          ? (e += `
                                <div class="table-container">
                                    <table>
                                        <thead>
                                            <tr>
                                                ${(s.headers || []).map((n) => `<th>${a(n)}</th>`).join("")}
                                            </tr>
                                        </thead>
                                        <tbody>
                                            ${(s.rows || []).map((n) => `<tr>${n.map((p) => `<td>${a(p)}</td>`).join("")}</tr>`).join("")}
                                        </tbody>
                                    </table>
                                </div>
                            `)
                          : s.type === "list"
                          ? (e += `<ul>${(s.items || []).map((n) => `<li><strong>${a(n.term)}:</strong> ${a(n.definition)}</li>`).join("")}</ul>`)
                          : s.type === "subcards" &&
                            (e += `<div class="subcards-container">${(s.items || []).map((n) => `<div class="subcard"><h4>${a(n.title)}</h4><p>${a(n.content)}</p></div>`).join("")}</div>`),
                          e;
                      })
                      .join("")}
                    ${
                      t.concepts.upscNotes && t.concepts.upscNotes.length > 0
                        ? `
                    <h3><span class="lang-en">UPSC Notes & Insights</span><span class="lang-hi">UPSC नोट्स और अंतर्दृष्टि</span></h3>
                    <div class="upsc-notes-container">
                        ${t.concepts.upscNotes.map((s) => `<div class="upsc-note ${s.type}"><p class="note-content"><i class="fas fa-lightbulb"></i> ${a(s.content)}</p></div>`).join("")}
                    </div>
                    `
                        : ""
                    }
                    ${
                      t.concepts.keyTakeaways && t.concepts.keyTakeaways.length > 0
                        ? `
                    <h3><span class="lang-en">Key Takeaways</span><span class="lang-hi">मुख्य बातें</span></h3>
                    <ul>
                        ${t.concepts.keyTakeaways.map((s) => `<li>${a(s)}</li>`).join("")}
                    </ul>
                    `
                        : ""
                    }
                `;
        break;
      case "visual":
        c = `
                    <h2><span class="lang-en">Visual Learning Aids</span><span class="lang-hi">दृश्य शिक्षण सहायता</span></h2>
                    ${(t.visual.visualBlocks || [])
                      .map((s) => {
                        let e = `<h4>${a(s.title)}</h4>`;
                        if (s.type === "timeline")
                          e += `<div class="timeline">${(s.data || []).map((n) => `<div class="timeline-item"><h5>${a(n.label)}</h5><p>${a(n.description)}</p></div>`).join("")}</div>`;
                        else if (s.type === "flow")
                          e += `<div class="flowchart">${(s.data || []).map((n) => `<span>${a(n)}</span>`).join(" &rarr; ")}</div>`;
                        else if (s.type === "tree") {
                          const n = (p) => {
                            let l = `<ul><li>${a(p.root || p.label)}`;
                            return (
                              p.branches && p.branches.length > 0 && (l += `<ul>${p.branches.map((d) => n(d)).join("")}</ul>`),
                              p.children && p.children.length > 0 && (l += `<ul>${p.children.map((d) => `<li>${a(d)}</li>`).join("")}</ul>`),
                              (l += "</li></ul>"),
                              l
                            );
                          };
                          e += `<div class="tree-view">${n(s.data)}</div>`;
                        } else
                          s.type === "table" &&
                            (e += `
                                <div class="table-container">
                                    <table>
                                        <thead>
                                            <tr>
                                                ${(s.headers || []).map((n) => `<th>${a(n)}</th>`).join("")}
                                            </tr>
                                        </thead>
                                        <tbody>
                                            ${(s.rows || []).map((n) => `<tr>${n.map((p) => `<td>${a(p)}</td>`).join("")}</tr>`).join("")}
                                        </tbody>
                                    </table>
                                </div>
                            `);
                        return e;
                      })
                      .join("")}
                `;
        break;
      case "comparisons":
        c = `
                    <h2><span class="lang-en">Comparisons & Connections</span><span class="lang-hi">तुलना और संबंध</span></h2>
                    ${
                      t.comparisons.differenceTables && t.comparisons.differenceTables.length > 0
                        ? `
                        ${t.comparisons.differenceTables
                          .map(
                            (s) => `
                            <h4>${a(s.title)}</h4>
                            <div class="table-container">
                                <table>
                                    <thead>
                                        <tr>
                                            ${(s.headers || []).map((e) => `<th>${a(e)}</th>`).join("")}
                                        </tr>
                                    </thead>
                                    <tbody>
                                        ${(s.rows || []).map((e) => `<tr>${e.map((n) => `<td>${a(n)}</td>`).join("")}</tr>`).join("")}
                                    </tbody>
                                </table>
                            </div>
                        `
                          )
                          .join("")}
                    `
                        : ""
                    }
                    ${
                      t.comparisons.similarityTables && t.comparisons.similarityTables.length > 0
                        ? `
                        ${t.comparisons.similarityTables
                          .map(
                            (s) => `
                            <h4>${a(s.title)}</h4>
                            <div class="table-container">
                                <table>
                                    <thead>
                                        <tr>
                                            ${(s.headers || []).map((e) => `<th>${a(e)}</th>`).join("")}
                                        </tr>
                                    </thead>
                                    <tbody>
                                        ${(s.rows || []).map((e) => `<tr>${e.map((n) => `<td>${a(n)}</td>`).join("")}</tr>`).join("")}
                                    </tbody>
                                </table>
                            </div>
                        `
                          )
                          .join("")}
                    `
                        : ""
                    }
                    ${
                      t.comparisons.evolution
                        ? `
                        <h4>${a(t.comparisons.evolution.title)}</h4>
                        <p>${(t.comparisons.evolution.steps || []).map((s) => a(s)).join(" &rarr; ")}</p>
                    `
                        : ""
                    }
                    ${
                      t.comparisons.frequentlyConfused && t.comparisons.frequentlyConfused.length > 0
                        ? `
                        <h3><span class="lang-en">Frequently Confused Concepts</span><span class="lang-hi">अक्सर भ्रमित अवधारणाएँ</span></h3>
                        <ul>
                            ${t.comparisons.frequentlyConfused.map((s) => `<li><strong>${a(s.topicA)}</strong> vs <strong>${a(s.topicB)}</strong>: ${a(s.clarification)}</li>`).join("")}
                        </ul>
                    `
                        : ""
                    }
                    ${
                      t.comparisons.conceptConnections && t.comparisons.conceptConnections.length > 0
                        ? `
                        <h3><span class="lang-en">Concept Connections</span><span class="lang-hi">अवधारणा संबंध</span></h3>
                        <ul>
                            ${t.comparisons.conceptConnections.map((s) => `<li><strong>${a(s.from)}</strong> to <strong>${a(s.to)}</strong>: ${a(s.relationship)}</li>`).join("")}
                        </ul>
                    `
                        : ""
                    }
                `;
        break;
      case "practice":
        c = `
                    <h2><span class="lang-en">Practice Questions</span><span class="lang-hi">अभ्यास प्रश्न</span></h2>
                    <div class="practice-questions-container">
                        ${Object.entries(t.practice.levels || {})
                          .map(
                            ([s, e]) => `
                            <div class="practice-level ${s}-level">
                                <h3>${a(s)} Questions</h3>
                                ${b(e)
                                  .map((n, p) => {
                                    let l = `<div class="practice-question-card"><div class="q-row"><div class="q-num-badge">${p + 1}</div><div class="q-body">`;
                                    return (
                                      n.question
                                        ? (l += `<p class="q-text-sm">${a(n.question)}</p>`)
                                        : n.statements
                                        ? ((l += `<p class="q-text-sm"><span class="lang-en">Consider the following statements:</span><span class="lang-hi">निम्नलिखित कथनों पर विचार करें:</span></p><ul>`),
                                          (l += n.statements.map((d) => `<li>${a(d.text || d)}</li>`).join("")),
                                          (l += `</ul>`))
                                        : n.assertion
                                        ? ((l += `<p class="q-text-sm"><strong><span class="lang-en">Assertion (A):</span><span class="lang-hi">अभिकथन (A):</span></strong> ${a(n.assertion)}</p>`),
                                          (l += `<p class="q-text-sm"><strong><span class="lang-en">Reason (R):</span><span class="lang-hi">कारण (R):</span></strong> ${a(n.reason)}</p>`))
                                        : n.pairs &&
                                          ((l += `<p class="q-text-sm">${a(n.question)}</p><div class="match-pairs">`),
                                          n.pairs.forEach((d) => {
                                            l += `<div class="match-item"><span>${a(d.left)}</span><span>${a(d.right)}</span></div>`;
                                          }),
                                          (l += "</div>")),
                                      (l += '<div class="options-container">'),
                                      (n.options || []).forEach((d) => {
                                        l += `
                                            <div class="practice-option-box">
                                                <label class="opt-label">
                                                    <input type="radio" name="p-${n.id}" class="opt-radio" data-q-id="${n.id}" data-opt-letter="${d.letter}">
                                                    <span><b>${d.letter}.</b> ${a(d.text)}</span>
                                                </label>
                                            </div>
                                        `;
                                      }),
                                      (l += `</div><div class="sol-box"><p class="sol-text"><strong><span class="lang-en">Answer:</span><span class="lang-hi">उत्तर:</span> ${n.correctAnswer || n.correctMapping || ""}</strong> ${a(n.explanation)}</p></div></div></div></div>`),
                                      l
                                    );
                                  })
                                  .join("")}
                            </div>
                        `
                          )
                          .join("")}
                    </div>
                `;
        break;
      case "mains":
        c = `
                    <h2><span class="lang-en">Mains Answer Writing</span><span class="lang-hi">मुख्य उत्तर लेखन</span></h2>
                    ${(t.mains.questions || [])
                      .map(
                        (s) => `
                        <div class="mains-question-card">
                            <h3>${a(s.question)} <span class="mains-marks">(${s.marks} Marks)</span></h3>
                            <h4><span class="lang-en">Expected Structure</span><span class="lang-hi">अपेक्षित संरचना</span></h4>
                            <ul>
                                ${(s.structure || []).map((e) => `<li>${a(e)}</li>`).join("")}
                            </ul>
                            ${
                              s.keywords && s.keywords.length > 0
                                ? `
                            <h4><span class="lang-en">Keywords</span><span class="lang-hi">मुख्य शब्द</span></h4>
                            <p>${s.keywords.map((e) => `<span class="keyword-tag">${a(e)}</span>`).join("")}</p>
                            `
                                : ""
                            }
                            <div class="model-answer-section">
                                <h4><span class="lang-en">Model Answer</span><span class="lang-hi">मॉडल उत्तर</span></h4>
                                <p><strong><span class="lang-en">Introduction:</span><span class="lang-hi">परिचय:</span></strong> ${a(s.modelAnswer?.introduction)}</p>
                                <p><strong><span class="lang-en">Body:</span><span class="lang-hi">मुख्य भाग:</span></strong> ${a(s.modelAnswer?.body)}</p>
                                <p><strong><span class="lang-en">Conclusion:</span><span class="lang-hi">निष्कर्ष:</span></strong> ${a(s.modelAnswer?.conclusion)}</p>
                            </div>
                            ${
                              s.valueAddition && s.valueAddition.length > 0
                                ? `
                            <h4><span class="lang-en">Value Addition</span><span class="lang-hi">मूल्य संवर्धन</span></h4>
                            <ul>
                                ${s.valueAddition.map((e) => `<li>${a(e)}</li>`).join("")}
                            </ul>
                            `
                                : ""
                            }
                            ${
                              s.diagram
                                ? `
                            <h4><span class="lang-en">Diagram/Flowchart</span><span class="lang-hi">आरेख/फ्लोचार्ट</span></h4>
                            <div class="diagram-container">
                                ${s.diagram.type === "flow" ? `<div class="flowchart">${(s.diagram.data || []).map((e) => `<span>${a(e)}</span>`).join(" &rarr; ")}</div>` : a(s.diagram.description)}
                            </div>
                            `
                                : ""
                            }
                        </div>
                    `
                      )
                      .join("")}
                `;
        break;
      case "revision":
        const i = t.revision || {};
        c = `
                    <h2><span class="lang-en">Revision Notes</span><span class="lang-hi">पुनरावृत्ति नोट्स</span></h2>
                    ${
                      i.onePageNotes && i.onePageNotes.columns
                        ? `
                    <div class="revision-grid">
                        ${i.onePageNotes.columns
                          .map(
                            (s) => `
                            <div class="revision-card">
                                <h3>${a(s.title)}</h3>
                                <ul>${(s.points || []).map((e) => `<li>${a(e)}</li>`).join("")}</ul>
                            </div>
                        `
                          )
                          .join("")}
                    </div>
                    `
                        : ""
                    }
                    ${
                      i.mnemonics && i.mnemonics.length > 0
                        ? `
                    <h3><span class="lang-en">Mnemonics</span><span class="lang-hi">स्मृति सहायक (Mnemonics)</span></h3>
                    <div class="revision-grid">
                        ${i.mnemonics
                          .map(
                            (s) => `
                            <div class="revision-card">
                                <h4>${a(s.phrase)}</h4>
                                <p><strong>${a(s.meaning)}</strong></p>
                                <p>${a(s.explanation)}</p>
                            </div>
                        `
                          )
                          .join("")}
                    </div>
                    `
                        : ""
                    }
                    ${
                      i.flashcards && i.flashcards.length > 0
                        ? `
                    <h3><span class="lang-en">Flashcards</span><span class="lang-hi">फ्लैशकार्ड</span></h3>
                    <div class="revision-grid">
                        ${i.flashcards
                          .map(
                            (s) => `
                            <div class="revision-card">
                                <h4>${a(s.question)}</h4>
                                <p>${a(s.answer)}</p>
                            </div>
                        `
                          )
                          .join("")}
                    </div>
                    `
                        : ""
                    }
                    ${
                      i.frequentlyConfusedFacts && i.frequentlyConfusedFacts.length > 0
                        ? `
                    <h3><span class="lang-en">Frequently Confused Facts</span><span class="lang-hi">अक्सर भ्रमित तथ्य</span></h3>
                    <ul>${i.frequentlyConfusedFacts.map((s) => `<li><strong>${a(s.misconception)}</strong> ${a(s.correction)}</li>`).join("")}</ul>
                    `
                        : ""
                    }
                    ${
                      i.examDaySheet
                        ? `
                    <h3><span class="lang-en">Exam Day Sheet</span><span class="lang-hi">परीक्षा दिवस शीट</span></h3>
                    ${i.examDaySheet.fiveFacts ? `<h4><span class="lang-en">Five Facts</span><span class="lang-hi">पांच मुख्य तथ्य</span></h4><ul>${i.examDaySheet.fiveFacts.map((s) => `<li>${a(s)}</li>`).join("")}</ul>` : ""}
                    ${i.examDaySheet.threeTraps ? `<h4><span class="lang-en">Three Traps</span><span class="lang-hi">तीन सावधानियां</span></h4><ul>${i.examDaySheet.threeTraps.map((s) => `<li>${a(s)}</li>`).join("")}</ul>` : ""}
                    ${i.examDaySheet.oneMnemonic ? `<div class="revision-card"><h4>${a(i.examDaySheet.oneMnemonic.phrase)}</h4><p>${a(i.examDaySheet.oneMnemonic.meaning)}</p></div>` : ""}
                    `
                        : ""
                    }
                `;
        break;
      case "test":
        const r = t.test || {},
          y = [
            ["mcq", "MCQs"],
            ["statementBased", "Statement Based"],
            ["match", "Match the Following"],
          ],
          w = (s, e, n) => {
            let p = `<div class="practice-question-card test-question-card"><div class="q-row"><div class="q-num-badge">${e + 1}</div><div class="q-body">`;
            return (
              (p += s.question ? `<p class="q-text-sm">${a(s.question)}</p>` : ""),
              s.statements && (p += `<ul>${s.statements.map((l) => `<li>${a(l.text || l)}</li>`).join("")}</ul>`),
              s.pairs && (p += `<div class="match-pairs">${s.pairs.map((l) => `<div class="match-item"><span>${a(l.left)}</span><span>${a(l.right)}</span></div>`).join("")}</div>`),
              (p += `<div class="options-container">${(s.options || [])
                .map(
                  (l) => `
                        <div class="practice-option-box"><label class="opt-label"><input type="radio" name="t-${n}-${s.id || e}" class="opt-radio"><span><b>${l.letter}.</b> ${a(l.text)}</span></label></div>
                    `
                )
                .join("")}</div>`),
              (p += `<div class="sol-box"><p class="sol-text"><strong><span class="lang-en">Answer:</span><span class="lang-hi">उत्तर:</span> ${s.correctAnswer || s.correctMapping || ""}</strong> ${a(s.explanation)}</p></div>`),
              (p += "</div></div></div>"),
              p
            );
          };
        c = `
                    <h2><span class="lang-en">Mock Test</span><span class="lang-hi">मॉडेल टेस्ट</span></h2>
                    ${y
                      .map(([s, e]) =>
                        r[s] && r[s].length > 0
                          ? `<h3><span class="lang-en">${e}</span><span class="lang-hi">${e}</span></h3><div class="practice-questions-container">${r[s].map((n, p) => w(n, p, s)).join("")}</div>`
                          : ""
                      )
                      .join("")}
                    ${
                      r.mains
                        ? `<h3><span class="lang-en">Mains Practice</span><span class="lang-hi">मुख्य परीक्षा अभ्यास</span></h3>${(Array.isArray(r.mains) ? r.mains : r.mains.questions || [r.mains])
                            .map(
                              (s) =>
                                `<div class="mains-question-card"><h4>${a(s.question)} ${s.marks ? `<span class="mains-marks">(${s.marks} Marks)</span>` : ""}</h4>${
                                  s.structure ? `<ul>${s.structure.map((e) => `<li>${a(e)}</li>`).join("")}</ul>` : ""
                                }${
                                  s.modelAnswer
                                    ? `<div class="model-answer-section">${
                                        s.modelAnswer.introduction ? `<p><strong><span class="lang-en">Introduction:</span><span class="lang-hi">परिचय:</span></strong> ${a(s.modelAnswer.introduction)}</p>` : ""
                                      }${s.modelAnswer.body ? `<p><strong><span class="lang-en">Body:</span><span class="lang-hi">मुख्य भाग:</span></strong> ${a(s.modelAnswer.body)}</p>` : ""}${
                                        s.modelAnswer.conclusion ? `<p><strong><span class="lang-en">Conclusion:</span><span class="lang-hi">निष्कर्ष:</span></strong> ${a(s.modelAnswer.conclusion)}</p>` : ""
                                      }</div>`
                                    : ""
                                }</div>`
                            )
                            .join("")}`
                        : ""
                    }
                `;
        break;
      default:
        c = `<h2><span class="lang-en">Content for ${o}</span><span class="lang-hi">${o} के लिए सामग्री</span></h2><p><span class="lang-en">Loading...</span><span class="lang-hi">लोड हो रहा है...</span></p>`;
    }
    m.innerHTML = c;
  };

  h.addEventListener("click", (o) => {
    const c = o.target.closest(".tab-btn");
    if (!c) return;
    h.querySelectorAll(".tab-btn").forEach((r) => {
      r.classList.remove("active"), r.setAttribute("aria-selected", "false");
    });
    c.classList.add("active"), c.setAttribute("aria-selected", "true");
    const i = c.dataset.tab.replace("tab-", "");
    $(i);
  });

  const u = h.querySelector(".tab-btn.active");
  if (u) {
    const o = u.dataset.tab.replace("tab-", "");
    $(o);
  } else {
    $("overview");
  }

  const v = document.getElementById("mains-tab-btn");
  v && (v.style.display = t.supportsMains ? "" : "none");
});
